def evaluate(current_reputation, observation, my_history, round_num):
    # Asymmetric update: punish defection more than reward cooperation
    if observation['action'] == 'cooperate':
        new_reputation = min(1.0, current_reputation + 0.15)
    else:  # defect
        new_reputation = max(-1.0, current_reputation - 0.35)

    # Apply slight decay in later rounds to emphasize recent behavior
    if round_num > 15:
        decay_factor = 0.98 + (0.01 * (round_num - 15) / 50)
        new_reputation = max(-1.0, min(1.0, new_reputation * decay_factor))

    return new_reputation


def decide(recipient_reputation, round_num, my_history):
    # Adaptive threshold: explore early, cooperate selectively late
    if round_num <= 5:
        threshold = -0.5  # High cooperation in early exploration phase
    elif round_num <= 15:
        threshold = 0.0   # Neutral stance in middle phase
    else:
        threshold = 0.15  # More selective in late phase

    # Adjust based on own recent history (indirect signal, not direct reciprocity)
    recent_actions = [h.get('action', None) for h in my_history[-5:]] if my_history else []
    recent_coops = sum(1 for a in recent_actions if a == 'cooperate')
    if recent_coops < 2:
        threshold = max(-0.8, threshold - 0.1)  # Encourage recovery if we've been defecting

    # Decision based on recipient reputation vs dynamic threshold
    return recipient_reputation >= threshold

